  1	/**
  2	 * @fileoverview Utilities for handling text-based numbered options in WhatsApp chatbot flows.
  3	 * Evolution API does not support clickable buttons, so we need to use text-based numbered lists.
  4	 */
  5	
  6	import { getSuggestedOptions } from '@barber-app/booking-fsm';
  7	
  8	/**
  9	 * Format a reply message with numbered options based on the current FSM context
 10	 * @param {string} reply - The original reply message from the FSM
 11	 * @param {object} context - The FSM context object
 12	 * @returns {string} - Formatted reply with numbered options when applicable
 13	 */
 14	export function formatReplyWithOptions(reply, context) {
 15	  // Add numbered options for current step if available
 16	  const options = getSuggestedOptions(context);
 17	  
 18	  if (options && options.length > 0) {
 19	    let formattedReply = `${reply}\n\n`;
 20	    
 21	    // Create numbered list for service or worker selection
 22	    options.forEach((option, index) => {
 23	      formattedReply += `${index + 1}. ${option}\n`;
 24	    });
 25	    
 26	    return formattedReply.trim();
 27	  }
 28	  
 29	  // Special handling for confirmation step
 30	  if (context.step === 6) {
 31	    return `${reply}\n\n1. Sim\n2. Não`;
 32	  }
 33	  
 34	  // For date and time steps, add format hints
 35	  if (context.step === 4) {
 36	    return `${reply}\n\nPor favor, digite a data no formato AAAA-MM-DD (exemplo: 2025-05-15)`;
 37	  }
 38	  
 39	  if (context.step === 5) {
 40	    return `${reply}\n\nPor favor, digite o horário no formato HH:MM (exemplo: 14:30)`;
 41	  }
 42	  
 43	  return reply;
 44	}
 45	
 46	/**
 47	 * Process numeric responses by converting them to the corresponding text options
 48	 * @param {string} text - The user's input text
 49	 * @param {object} context - The current FSM context
 50	 * @returns {string} - Processed text (converted option if numeric)
 51	 */
 52	export function processNumericInput(text, context) {
 53	  // Strip whitespace and check if input is a number
 54	  const numericInput = text.trim().match(/^(\d+)$/);
 55	  if (!numericInput) return text;
 56	  
 57	  const optionIndex = parseInt(numericInput[1], 10) - 1;
 58	  
 59	  // Handle service selection (step 2)
 60	  if (context.step === 2) {
 61	    const services = getSuggestedOptions(context);
 62	    if (services && optionIndex >= 0 && optionIndex < services.length) {
 63	      return services[optionIndex];
 64	    }
 65	  }
 66	  
 67	  // Handle worker selection (step 3)
 68	  if (context.step === 3) {
 69	    const workers = getSuggestedOptions(context);
 70	    if (workers && optionIndex >= 0 && optionIndex < workers.length) {
 71	      return workers[optionIndex];
 72	    }
 73	  }
 74	  
 75	  // Handle confirmation (step 6)
 76	  if (context.step === 6) {
 77	    if (optionIndex === 0) return 'sim';
 78	    if (optionIndex === 1) return 'não';
 79	  }
 80	  
 81	  return text;
 82	}
 83	
 84	/**
 85	 * Store user context between interactions
 86	 * Uses a memory cache with key format: '{shopId}:{phoneNumber}'
 87	 */
 88	export class ContextManager {
 89	  constructor() {
 90	    this.contexts = new Map();
 91	    
 92	    // Optional: Set a cleanup interval to prevent memory leaks
 93	    setInterval(() => this.cleanupOldContexts(), 3600000); // Clean every hour
 94	  }
 95	  
 96	  /**
 97	   * Get the key for storing a user's context
 98	   * @param {string} shopId - The shop/instance ID
 99	   * @param {string} phoneNumber - The user's phone number
100	   * @returns {string} - The storage key
101	   */
102	  getKey(shopId, phoneNumber) {
103	    return `${shopId}:${phoneNumber}`;
104	  }
105	  
106	  /**
107	   * Store a context for a user
108	   * @param {string} shopId - The shop/instance ID
109	   * @param {string} phoneNumber - The user's phone number
110	   * @param {object} context - The FSM context to store
111	   * @param {number} [ttl=3600000] - Time to live in ms (default: 1 hour)
112	   */
113	  setContext(shopId, phoneNumber, context, ttl = 3600000) {
114	    const key = this.getKey(shopId, phoneNumber);
115	    this.contexts.set(key, {
116	      context,
117	      expires: Date.now() + ttl
118	    });
119	  }
120	  
121	  /**
122	   * Get the stored context for a user
123	   * @param {string} shopId - The shop/instance ID
124	   * @param {string} phoneNumber - The user's phone number
125	   * @returns {object|null} - The stored context or null if not found/expired
126	   */
127	  getContext(shopId, phoneNumber) {
128	    const key = this.getKey(shopId, phoneNumber);
129	    const entry = this.contexts.get(key);
130	    
131	    if (!entry) return null;
132	    
133	    // Check if expired
134	    if (entry.expires < Date.now()) {
135	      this.contexts.delete(key);
136	      return null;
137	    }
138	    
139	    return entry.context;
140	  }
141	  
142	  /**
143	   * Delete a user's context, e.g., after completing a booking
144	   * @param {string} shopId - The shop/instance ID
145	   * @param {string} phoneNumber - The user's phone number
146	   */
147	  deleteContext(shopId, phoneNumber) {
148	    const key = this.getKey(shopId, phoneNumber);
149	    this.contexts.delete(key);
150	  }
151	  
152	  /**
153	   * Clean up expired contexts to prevent memory leaks
154	   * @private
155	   */
156	  cleanupOldContexts() {
157	    const now = Date.now();
158	    for (const [key, entry] of this.contexts.entries()) {
159	      if (entry.expires < now) {
160	        this.contexts.delete(key);
161	      }
162	    }
163	  }
164	}
