  1	/**
  2	 * WhatsApp filters utility for consistent filtering in frontend and backend
  3	 */
  4	
  5	/**
  6	 * Check if a phone number should be allowed based on whitelist/blacklist configuration
  7	 * 
  8	 * @param {string} number - The phone number to check (e.g., +123456789 or 123456789@c.us)
  9	 * @param {Object} whatsappConfig - The WhatsApp integration configuration 
 10	 * @returns {Object} Result object with allowed status and reason if blocked
 11	 */
 12	export function checkNumberFilter(number, whatsappConfig) {
 13	  // If WhatsApp integration is not enabled or config is missing, allow all
 14	  if (!whatsappConfig?.enabled) return { allowed: true };
 15	  
 16	  // Check if it's a group message
 17	  const isGroup = number.includes('@g.us');
 18	  if (isGroup && whatsappConfig.disableGroups) {
 19	    return { allowed: false, reason: 'group' };
 20	  }
 21	  
 22	  // Apply number filtering based on whitelist/blacklist
 23	  const filterMode = whatsappConfig.filterMode || 'whitelist';
 24	  const filterNumbers = whatsappConfig.filterNumbers || [];
 25	  
 26	  // Check if filtering should be applied
 27	  if (filterNumbers.length > 0) {
 28	    // Normalize phone number for comparison
 29	    const normalizedNumber = number.replace(/[^0-9+]/g, '');
 30	    
 31	    // Check if the number is in the filter list
 32	    const isInList = filterNumbers.some(num => {
 33	      const normalizedFilterNumber = num.replace(/[^0-9+]/g, '');
 34	      return normalizedNumber.includes(normalizedFilterNumber) || 
 35	            normalizedFilterNumber.includes(normalizedNumber);
 36	    });
 37	    
 38	    // For whitelist: block if NOT in list
 39	    // For blacklist: block if IN list
 40	    const shouldBlock = (filterMode === 'whitelist') ? !isInList : isInList;
 41	    
 42	    if (shouldBlock) {
 43	      return { allowed: false, reason: filterMode };
 44	    }
 45	  } else if (filterMode === 'whitelist' && filterNumbers.length === 0) {
 46	    // Empty whitelist means block all (unless it's just not configured)
 47	    return { allowed: false, reason: 'emptyWhitelist' };
 48	  }
 49	  
 50	  return { allowed: true };
 51	}
 52	
 53	/**
 54	 * Format a phone number for consistent comparison
 55	 * 
 56	 * @param {string} phoneNumber - The phone number to format 
 57	 * @returns {string} Normalized phone number
 58	 */
 59	export function normalizePhoneNumber(phoneNumber) {
 60	  // Remove any non-numeric characters except +
 61	  return phoneNumber.replace(/[^0-9+]/g, '');
 62	}
 63	
 64	/**
 65	 * Check if a phone number is in a list (for whitelist/blacklist)
 66	 * 
 67	 * @param {string} phoneNumber - The phone number to check 
 68	 * @param {Array<string>} phoneList - List of phone numbers to check against
 69	 * @returns {boolean} True if the number is in the list
 70	 */
 71	export function isPhoneNumberInList(phoneNumber, phoneList) {
 72	  if (!phoneList || phoneList.length === 0) return false;
 73	  
 74	  const normalizedNumber = normalizePhoneNumber(phoneNumber);
 75	  
 76	  return phoneList.some(num => {
 77	    const normalizedListNumber = normalizePhoneNumber(num);
 78	    // Check if either number contains the other to handle partial matches
 79	    return normalizedNumber.includes(normalizedListNumber) || 
 80	           normalizedListNumber.includes(normalizedNumber);
 81	  });
 82	}
 83	
 84	/**
 85	 * Create a human-readable message explaining why a message was blocked
 86	 * 
 87	 * @param {string} reason - The reason code why a message was blocked
 88	 * @returns {string} Human-readable explanation
 89	 */
 90	export function getBlockReasonMessage(reason) {
 91	  switch (reason) {
 92	    case 'group':
 93	      return 'A mensagem foi bloqueada porque veio de um grupo do WhatsApp e o atendimento em grupos está desativado.';
 94	    case 'whitelist':
 95	      return 'Este número não está na lista de números permitidos (whitelist).';
 96	    case 'blacklist':
 97	      return 'Este número está na lista de números bloqueados (blacklist).';
 98	    case 'emptyWhitelist':
 99	      return 'Nenhum número está configurado na lista de permissões (whitelist vazia).';
100	    default:
101	      return 'A mensagem foi bloqueada por regras de filtragem.';
102	  }
103	}

