  1	/**
  2	 * WhatsApp API Service
  3	 * 
  4	 * This service provides a simple interface for interacting with the
  5	 * Evolution API for WhatsApp messaging integration.
  6	 */
  7	
  8	// Common constants
  9	const EVOLUTION_API_URL = process.env.REACT_APP_EVO_BASE_URL || 'https://evolution-api-production-ad04.up.railway.app';
 10	const EVOLUTION_API_KEY = process.env.REACT_APP_EVO_API_KEY || '429683C4C977415CAAFCCE10F7D57E11';
 11	const INSTANCE_NAME = 'teste'; // Fixed instance name as currently configured
 12	
 13	/**
 14	 * Normalize a phone number for WhatsApp API
 15	 * 
 16	 * @param {string} phoneNumber - The phone number to normalize
 17	 * @returns {string} - Normalized phone number
 18	 */
 19	export function normalizePhoneNumber(phoneNumber) {
 20	  if (!phoneNumber) {
 21	    return '';
 22	  }
 23	  
 24	  // Handle WhatsApp format (with @c.us or @s.whatsapp.net)
 25	  let normalizedNumber = phoneNumber.toString().trim();
 26	  if (normalizedNumber.includes('@')) {
 27	    normalizedNumber = normalizedNumber.split('@')[0];
 28	  }
 29	  
 30	  // Remove any non-numeric characters except +
 31	  normalizedNumber = normalizedNumber.replace(/[^0-9+]/g, '');
 32	  
 33	  // Remove + sign if present (Evolution API doesn't use it)
 34	  if (normalizedNumber.startsWith('+')) {
 35	    normalizedNumber = normalizedNumber.substring(1);
 36	  }
 37	  
 38	  // Ensure the number is not empty after processing
 39	  if (!normalizedNumber) {
 40	    console.warn(`Invalid phone number format: ${phoneNumber}`);
 41	    return '';
 42	  }
 43	  
 44	  return normalizedNumber;
 45	}
 46	
 47	/**
 48	 * Send a text message via WhatsApp
 49	 * 
 50	 * @param {string} phoneNumber - The recipient's phone number
 51	 * @param {string} message - The message text to send
 52	 * @returns {Promise<Object>} - The API response
 53	 */
 54	export async function sendWhatsAppMessage(phoneNumber, message) {
 55	  try {
 56	    const normalizedNumber = normalizePhoneNumber(phoneNumber);
 57	    
 58	    if (!normalizedNumber) {
 59	      throw new Error('Invalid phone number format');
