 31	  reply: string;               // text to send back to the user
 32	  context: BookingContext;     // mutated copy (immutability for safety)
 33	  appointment?: {              // present only when user confirmed (step 6 → "sim")
 34	    worker_id: string | number;
 35	    date: string;
 36	    start_time: string;
